 @Override protected void onCreate(Bundle state){super.onCreate(state);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);WindowInsetsControllerCompat ic=WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView());ic.setAppearanceLightStatusBars(true);ic.setAppearanceLightNavigationBars(true);setContentView(R.layout.activity_main);View root=findViewById(R.id.rootLayout);ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{Insets b=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());v.setPadding(v.getPaddingLeft(),b.top,v.getPaddingRight(),b.bottom);return insets;});ViewCompat.requestApplyInsets(root);((MaterialToolbar)findViewById(R.id.topAppBar)).setTitle("DeleteMe");container=findViewById(R.id.screenContainer);nav=findViewById(R.id.bottomNavigation);nav.setOnItemSelectedListener(i->{if(i.getItemId()==R.id.nav_scan){showScan();return true;}if(i.getItemId()==R.id.nav_results){showResults();return true;}if(i.getItemId()==R.id.nav_settings){showSettings();return true;}return false;});nav.setSelectedItemId(R.id.nav_scan);}
 private void showScan(){View v=getLayoutInflater().inflate(R.layout.screen_scan,container,false);container.removeAllViews();container.addView(v);input=v.findViewById(R.id.identifierInput);inputLayout=v.findViewById(R.id.identifierLayout);searchHelp=v.findViewById(R.id.searchHelp);Chip e=v.findViewById(R.id.typeEmail),m=v.findViewById(R.id.typeMobile),u=v.findViewById(R.id.typeUsername),n=v.findViewById(R.id.typeName);e.setOnClickListener(x->type("email"));m.setOnClickListener(x->type("mobile"));u.setOnClickListener(x->type("username"));n.setOnClickListener(x->type("name"));MaterialButton b=v.findViewById(R.id.findButton);b.setOnClickListener(x->scan(b));}
 private void type(String t){searchType=t;input.setText("");inputLayout.setError(null);if(t.equals("email")){inputLayout.setHint("Email address");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);searchHelp.setText("Checks free breach intelligence and shows the reported breach details.");}else if(t.equals("mobile")){inputLayout.setHint("Mobile number");input.setInputType(InputType.TYPE_CLASS_PHONE);searchHelp.setText("Checks supported public sources. A removal directory entry is not evidence that your number was found.");}else if(t.equals("username")){inputLayout.setHint("Username / handle");input.setInputType(InputType.TYPE_CLASS_TEXT);searchHelp.setText("Checks public GitHub and GitLab profiles. Matches are possible matches, not identity proof.");}else{inputLayout.setHint("Full name");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);searchHelp.setText("Checks public developer profiles. Name matches are possible matches, not identity proof.");}}
 private void scan(MaterialButton b){String v=input.getText()==null?"":input.getText().toString().trim();if(v.isEmpty()){inputLayout.setError("Enter something to search");return;}if(searchType.equals("email")&&!android.util.Patterns.EMAIL_ADDRESS.matcher(v).matches()){inputLayout.setError("Enter a valid email address");return;}if(searchType.equals("mobile")&&v.replaceAll("\\D","").length()<8){inputLayout.setError("Enter a valid mobile number");return;}if((searchType.equals("username")||searchType.equals("name"))&&v.length()<2){inputLayout.setError("Enter at least 2 characters");return;}lastIdentifier=v;inputLayout.setError(null);b.setEnabled(false);b.setText("Searching…");executor.execute(()->{try{breaches.clear();publicMatches.clear();if(searchType.equals("email"))loadEmail(v);else if(searchType.equals("username"))loadUsername(v);else if(searchType.equals("name"))loadName(v);else loadMobile(v);runOnUiThread(()->{b.setEnabled(true);b.setText("Find my data  →");showResults();});}catch(Exception e){runOnUiThread(()->{b.setEnabled(true);b.setText("Try again");Toast.makeText(this,"Search failed. Check your connection.",Toast.LENGTH_LONG).show();});}});}
 private void loadEmail(String email)throws Exception{String s=get(XON+"breach-analytics?email="+URLEncoder.encode(email,"UTF-8"));JSONObject r=new JSONObject(s);JSONObject eb=r.optJSONObject("ExposedBreaches");JSONArray a=eb==null?null:eb.optJSONArray("breaches_details");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)breaches.add(new BreachResult(x.optString("breach","Unknown source"),x.optString("domain",""),x.optString("xposed_date",""),x.optString("xposed_data",""),x.optLong("xposed_records",0),x.optString("details",""),x.optString("references",""),x.optString("password_risk","")));}}
 private void loadUsername(String u)throws Exception{String q=URLEncoder.encode(u,"UTF-8");if(code(GH+"users/"+q)==200)publicMatches.add(new PublicMatch("GitHub","Public profile","https://github.com/"+u,"Public username match."));if(code(GL+"users?username="+q)==200){JSONArray a=new JSONArray(get(GL+"users?username="+q));if(a.length()>0)publicMatches.add(new PublicMatch("GitLab","Public profile","https://gitlab.com/"+u,"Public username match."));}}
 private void loadName(String n)throws Exception{JSONObject o=new JSONObject(get(GH+"search/users?q="+URLEncoder.encode(n,"UTF-8")+"&per_page=10"));JSONArray a=o.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)publicMatches.add(new PublicMatch("GitHub","Possible public profile","https://github.com/"+x.optString("login"),"Returned by GitHub name search."));}}
 private void loadMobile(String mobile){ }
 private void showResults(){nav.getMenu().findItem(R.id.nav_results).setChecked(true);container.removeAllViews();ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.addView(s);label(r,"SCAN RESULTS");int total=breaches.size()+publicMatches.size();r.addView(text(total+" result"+(total==1?"":"s")+" found",30,INK,true),margin(0,7,0,5));r.addView(text(breaches.size()>0?"Review the exact source, date and exposed data before deciding whether to remove anything.":"Review each public match before deciding whether to request removal.",15,MUTED,false),margin(0,0,0,15));LinearLayout st=row();r.addView(st,margin(0,0,0,12));st.addView(stat("CONFIRMED EXPOSURES",String.valueOf(breaches.size()),RED_BG,RED),weight());addSpace(st,10);st.addView(stat("PUBLIC MATCHES",String.valueOf(publicMatches.size()),BLUE_BG,BLUE),weight());MaterialButton dir=primaryButton("🇮🇳  Browse removal options");dir.setOnClickListener(v->showDirectory(lastIdentifier));r.addView(dir,margin(0,2,0,16));for(BreachResult b:breaches)addBreach(r,b);for(PublicMatch p:publicMatches)addPublic(r,p);if(total==0)addEmpty(r);}
 private void addBreach(LinearLayout r,BreachResult b){MaterialCardView c=card(WHITE,RED);LinearLayout x=column(17,17,17,17);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(badge("🔴  CONFIRMED EXPOSURE",RED),margin(0,0,0,10));x.addView(text(b.name,21,INK,true));if(!b.domain.isEmpty())x.addView(text(b.domain,13,MUTED,false),margin(0,2,0,10));if(!b.date.isEmpty())x.addView(meta("📅","Breach date",b.date),margin(0,0,0,8));if(b.records>0)x.addView(meta("👥","Records affected",format(b.records)),margin(0,0,0,8));if(!b.data.isEmpty()){x.addView(text("DATA EXPOSED",11,MUTED,true),margin(0,3,0,5));x.addView(chips(b.data),margin(0,0,0,10));}if(!b.description.isEmpty()){x.addView(text("WHAT HAPPENED",11,MUTED,true),margin(0,2,0,4));x.addView(text(b.description,13,MUTED,false),margin(0,0,0,9));}if(!b.passwordRisk.isEmpty())x.addView(text("PASSWORD RISK  ·  "+b.passwordRisk,12,b.passwordRisk.toLowerCase().contains("plain")?RED:ORANGE,true),margin(0,0,0,8));LinearLayout a=row();x.addView(a);MaterialButton review=primaryButton("Review removal →");review.setOnClickListener(v->showRemovalReview(b));a.addView(review,weight());addSpace(a,8);MaterialButton keep=secondaryButton("Keep");keep.setOnClickListener(v->c.setVisibility(View.GONE));a.addView(keep,weight());}
 private void addPublic(LinearLayout r,PublicMatch p){MaterialCardView c=card(BLUE_BG,BLUE);LinearLayout x=column(16,15,16,15);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(badge("🔵  POSSIBLE PUBLIC MATCH",BLUE),margin(0,0,0,9));x.addView(text(p.source,19,INK,true));x.addView(text(p.kind,13,BLUE,true),margin(0,2,0,5));x.addView(text("Where: "+p.url,12,MUTED,false));x.addView(text(p.note,13,MUTED,false),margin(0,5,0,9));MaterialButton b=primaryButton("Review removal →");b.setOnClickListener(v->showPublicRemoval(p));x.addView(b);}
 private void showRemovalReview(BreachResult b){nav.getMenu().findItem(R.id.nav_results).setChecked(true);ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.removeAllViews();container.addView(s);label(r,"REMOVAL REVIEW");r.addView(text("Review before removing",28,INK,true),margin(0,7,0,4));r.addView(text("This screen is about this specific exposure, not the general directory.",14,MUTED,false),margin(0,0,0,14));MaterialCardView source=card(WHITE,RED);LinearLayout x=column(17,17,17,17);source.addView(x);r.addView(source,margin(0,0,0,12));x.addView(badge("🔴  DATA FOUND HERE",RED),margin(0,0,0,10));x.addView(text(b.name,22,INK,true));if(!b.domain.isEmpty())x.addView(text(b.domain,13,MUTED,false));addDetail(x,"When",b.date.isEmpty()?"Date not returned":b.date);addDetail(x,"Data exposed",b.data.isEmpty()?"Not returned by source":b.data);if(b.records>0)addDetail(x,"Records",format(b.records));if(!b.passwordRisk.isEmpty())addDetail(x,"Password risk",b.passwordRisk);if(!b.description.isEmpty())addDetail(x,"What happened",b.description);}
 private void showPublicRemoval(PublicMatch p){ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.removeAllViews();container.addView(s);label(r,"REMOVAL REVIEW");r.addView(text("Review this public match",28,INK,true),margin(0,7,0,4));MaterialCardView c=card(BLUE_BG,BLUE);LinearLayout x=column(17,17,17,17);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(badge("🔵  POSSIBLE PUBLIC MATCH",BLUE),margin(0,0,0,10));x.addView(text(p.source,21,INK,true));addDetail(x,"Where found",p.url);addDetail(x,"Finding",p.note);addDetail(x,"Confidence","Possible match only. Verify it belongs to you before removal.");addRemovalDecision(r,p.source,p.url,searchType,"public profile");}
 private void addRemovalDecision(LinearLayout r,String source,String url,String type,String foundData){MaterialCardView c=card(WHITE,GREEN);LinearLayout x=column(17,17,17,17);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(text("What will removal do?",19,INK,true));x.addView(text("It asks the provider to remove, hide, or delete the profile/data associated with you. It does not erase historical copies already outside that provider.",13,MUTED,false),margin(0,5,0,12));x.addView(text("HOW DELETEME CAN ACT",11,MUTED,true),margin(0,0,0,5));x.addView(text("No automated deletion API is connected for this provider.",14,ORANGE,true));x.addView(text("The safe action is to use the provider's official route. Do not send passwords or unrelated personal data.",13,MUTED,false),margin(0,4,0,10));MaterialButton open=primaryButton("Open official removal route →");open.setOnClickListener(v->open(url));x.addView(open);TextView steps=text("Manual guide\n1. Open the official route.\n2. Verify the profile/contact details belong to you.\n3. Request deletion or unlisting.\n4. Complete any verification requested by the provider.\n5. Return here and mark this action as submitted.",13,INK,false);x.addView(steps,margin(0,12,0,8));MaterialButton done=secondaryButton("Mark removal submitted");done.setOnClickListener(v->{done.setText("Removal submitted ✓");done.setEnabled(false);});x.addView(done);MaterialButton keep=secondaryButton("Don't remove this");keep.setOnClickListener(v->showResults());x.addView(keep);}
 private void showDirectory(String context){ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.removeAllViews();container.addView(s);label(r,"REMOVAL OPTIONS");r.addView(text("Choose where to remove",28,INK,true),margin(0,7,0,4));r.addView(text("These are official removal opportunities. They are not proof that the service currently has your data.",14,MUTED,false),margin(0,0,0,15));if(!context.isEmpty())addContext(r,context);label(r,"🇮🇳  INDIA SOURCES");for(String[] a:INDIA)if(a[4].equals("any")||matches(a[4],searchType))addRoute(r,a[0],a[1],a[2],a[3],ORANGE_BG,ORANGE);label(r,"GLOBAL BROKER REGISTRY");executor.execute(()->{try{JSONArray a=brokerArray();runOnUiThread(()->{for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String n=first(o,"company","name","broker"),u=first(o,"optOutUrl","opt_out_url","optout_url","opt_out","url");if(!n.isEmpty()&&!u.isEmpty())addRoute(r,n,"Data broker",u,"Official route. Not a confirmed finding.",WHITE,MUTED);}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Global directory unavailable.",Toast.LENGTH_LONG).show());}});}
 private void addContext(LinearLayout r,String c){MaterialCardView v=card(GREEN_BG,GREEN);LinearLayout x=column(15,15,15,15);v.addView(x);r.addView(v,margin(0,0,0,15));x.addView(text("YOU ARE REVIEWING",11,GREEN,true));x.addView(text(c,18,INK,true),margin(0,4,0,0));x.addView(text("The provider below is a removal opportunity, not automatically a confirmed breach source.",13,MUTED,false),margin(0,4,0,0));}
 private void addRoute(LinearLayout r,String name,String category,String url,String note,int bg,int accent){MaterialCardView c=card(bg,accent);LinearLayout x=column(16,15,16,15);c.addView(x);r.addView(c,margin(0,0,0,10));x.addView(text(name,18,INK,true));x.addView(text(category,12,accent,true),margin(0,3,0,4));x.addView(text(note,13,MUTED,false),margin(0,0,0,9));MaterialButton b=primaryButton("Review removal →");b.setOnClickListener(v->showRouteReview(name,category,url,note));x.addView(b);}
 private void showRouteReview(String name,String category,String url,String note){ScrollView s=new ScrollView(this);s.setBackgroundColor(BG);LinearLayout r=column(20,18,20,30);s.addView(r);container.removeAllViews();container.addView(s);label(r,"REMOVAL REVIEW");r.addView(text(name,28,INK,true),margin(0,7,0,3));r.addView(text(category,13,ORANGE,true),margin(0,0,0,12));MaterialCardView c=card(WHITE,ORANGE);LinearLayout x=column(17,17,17,17);c.addView(x);r.addView(c,margin(0,0,0,12));x.addView(badge("🟠  REMOVAL OPPORTUNITY",ORANGE),margin(0,0,0,10));addDetail(x,"Why shown","This provider has an official removal route in DeleteMe's directory. This does not mean your data was found here.");addDetail(x,"Identifier","Your selected scan identifier");addDetail(x,"Route",url);addRemovalDecision(r,name,url,searchType,"directory listing");}
 private void addDetail(LinearLayout x,String k,String v){x.addView(text(k.toUpperCase(),10,MUTED,true),margin(0,7,0,2));x.addView(text(v,14,INK,false));}
 private boolean matches(String a,String b){return a.equals("any")||a.equals(b)||a.equals("phone")&&b.equals("mobile")||a.equals("profile")&&(b.equals("username")||b.equals("name"));}
 private void addEmpty(LinearLayout r){MaterialCardView c=card(GREEN_BG,GREEN);LinearLayout x=column(20,24,20,24);c.addView(x);r.addView(c,margin(0,0,0,10));TextView q=text("✓",36,GREEN,true);q.setGravity(Gravity.CENTER);x.addView(q);TextView h=text("No confirmed exposure found",19,INK,true);h.setGravity(Gravity.CENTER);x.addView(h,margin(0,6,0,4));TextView d=text("The checked source did not return a matching exposure. Removal options below are separate from confirmed findings.",13,MUTED,false);d.setGravity(Gravity.CENTER);x.addView(d);}
