 private LinearLayout column(int l,int t,int rr,int b){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(l,t,rr,b);return x;}private LinearLayout row(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.HORIZONTAL);x.setGravity(Gravity.CENTER_VERTICAL);return x;}private LinearLayout.LayoutParams weight(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);return p;}private void addSpace(LinearLayout x,int n){Space s=new Space(this);x.addView(s,new LinearLayout.LayoutParams(n,1));}private LinearLayout.LayoutParams margin(int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(l,t,r,b);return p;}private TextView text(String s,float z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,1);return t;}private void label(LinearLayout r,String s){r.addView(text(s,12,GREEN,true),margin(0,0,0,3));}private MaterialCardView card(int bg,int stroke){MaterialCardView c=new MaterialCardView(this);c.setCardBackgroundColor(bg);c.setStrokeColor(stroke);c.setStrokeWidth(1);c.setRadius(20);c.setCardElevation(0);return c;}private TextView badge(String s,int c){TextView t=text(s,11,WHITE,true);t.setPadding(10,6,10,6);t.setBackgroundColor(c);return t;}private MaterialCardView stat(String a,String b,int bg,int c){MaterialCardView v=card(bg,c);LinearLayout x=column(13,13,13,13);v.addView(x);x.addView(text(a,10,c,true));x.addView(text(b,25,INK,true));return v;}private TextView meta(String i,String k,String v){return text(i+"  "+k+"\n"+v,13,INK,false);}private LinearLayout chips(String data){LinearLayout x=row();String[] p=data.split("[,;|]");int n=0;for(String q:p){q=q.trim();if(q.isEmpty())continue;TextView t=text(q,12,INK,false);t.setPadding(10,6,10,6);t.setBackgroundColor(Color.rgb(235,238,241));LinearLayout.LayoutParams z=new LinearLayout.LayoutParams(-2,-2);z.setMargins(0,0,6,6);x.addView(t,z);if(++n>=8)break;}return x;}private MaterialButton primaryButton(String s){MaterialButton b=new MaterialButton(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(WHITE);b.setBackgroundColor(GREEN);return b;}private MaterialButton secondaryButton(String s){MaterialButton b=new MaterialButton(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(INK);b.setBackgroundColor(WHITE);return b;}private void open(String u){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){Toast.makeText(this,"No app can open this route.",Toast.LENGTH_SHORT).show();}}private String get(String u)throws Exception{return read((HttpURLConnection)new URL(u).openConnection());}private int code(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);return c.getResponseCode();}private String read(HttpURLConnection c)throws Exception{c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/json");int z=c.getResponseCode();if(z<200||z>=300)throw new IOException("HTTP "+z);InputStream i=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1)o.write(b,0,n);i.close();return o.toString(StandardCharsets.UTF_8.name());}private JSONArray brokerArray()throws Exception{Object o=new JSONTokener(get(BROKERS)).nextValue();if(o instanceof JSONArray)return(JSONArray)o;JSONObject x=(JSONObject)o;JSONArray a=x.optJSONArray("data");if(a==null)a=x.optJSONArray("brokers");return a==null?new JSONArray():a;}private String first(JSONObject o,String...k){for(String q:k){String v=o.optString(q,"");if(!v.trim().isEmpty())return v.trim();}return "";}private String format(long n){return String.format(Locale.US,"%,d",n);}
 static class BreachResult{String name,domain,date,data;long records;String description,references,passwordRisk;BreachResult(String a,String b,String c,String d,long e,String f,String g,String h){name=a;domain=b;date=c;data=d;records=e;description=f;references=g;passwordRisk=h;}}
 static class PublicMatch{String source,kind,url,note;PublicMatch(String a,String b,String c,String d){source=a;kind=b;url=c;note=d;}}
 @Override protected void onDestroy(){executor.shutdownNow();super.onDestroy();}
